package br.com.dio.service;import br.com.dio.Modelo.Board;import br.com.dio.Modelo.GamestartEnum;import br.com.dio.Modelo.Space;import java.util.*;public class BoardService {    private final static int BOARD_LIMIT = 9;    private final Board board;    public BoardService(final Map<String, String> gameConfig) {        this.board = new Board(initBoard(gameConfig));    }    public List<List<Space>> getSpace(){        return this.board.getSpaces();    }    public void reset(){        this.board.reset();    }    public boolean hasErrors(){        return this.board.hasError();    }    public GamestartEnum getStatus(){        return this.board.getStatus();    }    public boolean gameIsFinished(){        return this.board.gameIsFinished();    }    private List<List<Space>> initBoard(Map<String, String> gameConfig) {        List<List<Space>> sp = new ArrayList<>();        for(int i = 0; i <= BOARD_LIMIT; i++){            sp.add(new ArrayList<>());            for(int j =0; j <BOARD_LIMIT; j++){                String positionConfig = gameConfig.get("%s,%s".formatted(i,j));                if(positionConfig ==null){                    sp.get(i).add(new Space(0,false));                    continue;                }                var expected = Integer.parseInt(positionConfig.split(";")[0]);                boolean fixed = Boolean.parseBoolean(positionConfig.split(";")[1]);                var currentSpace = new Space(expected, fixed);                sp.get(i).add(currentSpace);            }        }        return sp;    }}